// ask-fix-t1 (small_talk.how_that, route2.py last_next and how_that): "ok and how do I do that", by Helper's last line
const HT = ST.how_that
const BARE_AFTER = ['row', 'plain', 'then', 'rowthen', 'nextline', 'term', 'fact', 'want']
